INSERT INTO email_templates (template_type, name, subject, content, is_active) VALUES

('test_email', 'Test Email Template', 'Test Email from TalentXcel', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8" /><title>Test Email</title><meta name="viewport" content="width=device-width, initial-scale=1.0" /><style>body { margin: 0; padding: 0; background-color: #f3f4f6; font-family: ''Segoe UI'', ''Helvetica Neue'', sans-serif; color: #1a1a1a; }.container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }.header { background: linear-gradient(to right, #1e3a8a, #2563eb); padding: 24px; text-align: center; color: #ffffff; }.logo { font-size: 24px; font-weight: bold; text-decoration: none; display: block; color: #ffffff; }.logo span { color: #facc15; }.body { padding: 32px 24px; }.body p { font-size: 15px; line-height: 1.6; margin-bottom: 16px; }.footer { padding: 20px; background-color: #f1f5f9; font-size: 12px; text-align: center; color: #6b7280; }</style></head><body><div class="container"><div class="header"><a href="https://talentxcel.in" class="logo">Talent<span>Xcel</span></a><h2 style="margin: 10px 0;">Test Email</h2></div><div class="body"><p>Hi {{recipient_name}},</p><p>This is a test email to verify our email system is working correctly.</p><p>If you receive this email, everything is functioning properly!</p></div><div class="footer">© 2025 TalentXcel Services</div></div></body></html>', true),

('welcome_email', 'Welcome Email Alternative Template', 'Welcome to Your New Career Journey!', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8" /><title>Welcome</title><meta name="viewport" content="width=device-width, initial-scale=1.0" /><style>body { margin: 0; padding: 0; background-color: #f3f4f6; font-family: ''Segoe UI'', ''Helvetica Neue'', sans-serif; color: #1a1a1a; }.container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }.header { background: linear-gradient(to right, #1e3a8a, #2563eb); padding: 24px; text-align: center; color: #ffffff; }.logo { font-size: 24px; font-weight: bold; text-decoration: none; display: block; color: #ffffff; }.logo span { color: #facc15; }.body { padding: 32px 24px; }.body p { font-size: 15px; line-height: 1.6; margin-bottom: 16px; }.cta { text-align: center; margin-top: 20px; }.cta a { background-color: #1e40af; color: white; text-decoration: none; padding: 14px 28px; font-weight: bold; border-radius: 6px; display: inline-block; }.footer { padding: 20px; background-color: #f1f5f9; font-size: 12px; text-align: center; color: #6b7280; }</style></head><body><div class="container"><div class="header"><a href="https://talentxcel.in" class="logo">Talent<span>Xcel</span></a><h2 style="margin: 10px 0;">Welcome!</h2></div><div class="body"><p>Hi {{candidate_name}},</p><p>Welcome to TalentXcel! We''re excited to help you advance your career.</p><div class="cta"><a href="https://talentxcel.in/dashboard">Explore Dashboard</a></div></div><div class="footer">© 2025 TalentXcel Services</div></div></body></html>', true),

('job_status_update', 'Job Status Update Template', 'Update on Your Application - {{job_title}}', '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8" /><title>Application Update</title><meta name="viewport" content="width=device-width, initial-scale=1.0" /><style>body { margin: 0; padding: 0; background-color: #f3f4f6; font-family: ''Segoe UI'', ''Helvetica Neue'', sans-serif; color: #1a1a1a; }.container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }.header { background: linear-gradient(to right, #1e3a8a, #2563eb); padding: 24px; text-align: center; color: #ffffff; }.logo { font-size: 24px; font-weight: bold; text-decoration: none; display: block; color: #ffffff; }.logo span { color: #facc15; }.body { padding: 32px 24px; }.body p { font-size: 15px; line-height: 1.6; margin-bottom: 16px; }.cta { text-align: center; margin-top: 20px; }.cta a { background-color: #1e40af; color: white; text-decoration: none; padding: 14px 28px; font-weight: bold; border-radius: 6px; display: inline-block; }.footer { padding: 20px; background-color: #f1f5f9; font-size: 12px; text-align: center; color: #6b7280; }</style></head><body><div class="container"><div class="header"><a href="https://talentxcel.in" class="logo">Talent<span>Xcel</span></a><h2 style="margin: 10px 0;">Application Update</h2></div><div class="body"><p>Hi {{candidate_name}},</p><p>We have an update on your application for <strong>{{job_title}}</strong> at <strong>{{company_name}}</strong>.</p><p><strong>Status:</strong> {{application_status}}</p><p>{{status_message}}</p><div class="cta"><a href="https://talentxcel.in/applications">View Application</a></div></div><div class="footer">© 2025 TalentXcel Services</div></div></body></html>', true),

